import urllib.request,json
base='http://127.0.0.1:17448'
def get(route):
 with urllib.request.urlopen(base+route,timeout=4) as response:return json.load(response)
s=get('/api/status')
h=get('/api/health')
c=get('/api/projects/control-plane/cutover-r42/status')
sections={}
for k in ('agentAssignmentCutover','agentControlHealth','operatorLifecycle','operational','queue','agentAssignments'):
 raw=s.get(k)
 if isinstance(raw,dict):
  kept={}
  for name,val in raw.items():
   if name in ('status','state','mode','queuePaused','reconciliationRequired','pendingUnknown','unknownEffectCount','pendingUnknownCount','blocked','queued','active','failed','holdActive','ready','paused','reason','reasonCode','healthState','dispatchInFlight','enabled','allowAutonomousSend','error','oldestQueuedAgeMs'):
    if isinstance(val,(str,bool,int,float)) or val is None:kept[name]=val
  sections[k]={'keys':list(raw)[:35],'flags':kept}
  if k=='agentAssignments':
   row=raw.get('counts')
   if isinstance(row,dict):sections[k]['counts']=row
 else: sections[k]={'type':type(raw).__name__}
print(json.dumps({'status':sections,'health':{'state':h.get('state'),'reasons':h.get('reasons'),'queueDisposition':(h.get('queueSafety') or {}).get('queueDisposition')},'cutover':{'holdActive':c.get('cutoverState',{}).get('holdActive'),'original':{k:c.get('cutoverState',{}).get('originalAutonomy',{}).get(k) for k in ('enabled','mode','allowAutonomousSend','autoContinueEnabled')}},'readOnly':True},ensure_ascii=True)[:7200])
